function parse_nested_parens(paren_string){
  return paren_string.split(' ')
    .map(group => {
      let max_depth = 0;
      let current_depth = 0;
      for (let char of group) {
        if (char === '(') {
          current_depth++;
          max_depth = Math.max(max_depth, current_depth);
        } else if (char === ')') {
          current_depth--;
        }
      }
      return max_depth;
    });
}

