        let sum = 1;
        for (let i = 2; i <= Math.sqrt(num); i++) {
            if (num % i === 0) {
                sum += i + num / i;
            }
        }
        return sum === num && num !== 1;
    }

    let sum = 0;
    for (let i = 2; i <= limit; i++) {
        if (isAmicable(i)) {
            sum += i;
        }
    }
    return sum;
}

function tri(n){
  if (n === 0) return [];
  if (n === 1) return [3];
  if (n === 2) return [3, 2];

  let sequence = [3, 2, 8];
  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      sequence.push(1 + i / 2);
    } else {
      sequence.push(sequence[i - 1] + sequence[i - 2] + sequence[i + 1]);
    }
  }
  return sequence;
}

