function pancake_sort(nums){
    function flip(nums, k) {
        for (let i = 0; i < k / 2; i++) {
            [nums[i], nums[k - i - 1]] = [nums[k - i - 1], nums[i]];
        }
    }

    function findMaxIndex(nums, n) {
        let maxIndex = 0;
        for (let i = 1; i < n; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }
        return maxIndex;
    }

    for (let i = nums.length - 1; i > 0; i--) {
        let maxIndex = findMaxIndex(nums, i + 1);
        flip(nums, maxIndex + 1);
        flip(nums, i + 1);
    }

    return nums;
}

