function is_multiply_prime(a) {
  if (a < 2) return false;

  let primeCount = 0;

  for (let i = 2; i <= a; i++) {
    if (a % i === 0) {
      primeCount++;
      if (primeCount > 3) return false; // More than 3 prime factors
      for (let j = 2; j * j <= i; j++) {
        if (i % j === 0) break;
      }
      if (j * j > i) primeCount++; // i is prime
    }
  }

  return primeCount === 3;
}

