function encode(message) {
  const vowels = 'aeiouAEIOU';
  const vowelsMap = {
    a: 'c', e: 'g', i: 'k', o: 'q', u: 'w',
    A: 'C', E: 'G', I: 'K', O: 'Q', U: 'W'
  };

  return message.split('').map(char => {
    if (vowels.includes(char)) {
      const nextVowel = vowelsMap[char];
      const index = vowels.indexOf(char);
      const nextIndex = (index + 2) % vowels.length;
      return vowels[nextIndex];
    } else {
      return char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
    }
  }).join('');
}

function encode(message){
  const vowels = 'aeiouAEIOU';
  const replacements = 'cdefghijklmnopqrstvwxyzCDEFGHIJKLMNOPQRSTUVWXYZ';

  return message.split('').map(char => {
    if (vowels.includes(char)) {
      const nextVowelIndex = (vowels.indexOf(char) + 2) % vowels.length;
      return replacements[nextVowelIndex];
    }
    return char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
  }).join('');
}

