  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      sequence.push(sequence[i - 1] + sequence[i - 2]);
    } else {
      let next = sequence[i - 1] + sequence[i - 2] + sequence[i + 1];
      sequence.push(next);
    }
  }

  return sequence;
}

