function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to be between 0 and 1
  let rNorm = r / 255;
  let gNorm = g / 255;
  let bNorm = b / 255;

  // Find the maximum and minimum values
  let max = Math.max(rNorm, gNorm, bNorm);
  let min = Math.min(rNorm, gNorm, bNorm);

  // Calculate the hue
  let hue = 0;
  if (max === min) {
    hue = 0;
  } else if (max === rNorm) {
    hue = (60 * ((gNorm - bNorm) / (max - min))) % 360;
  } else if (max === gNorm) {
    hue = (60 * ((bNorm - rNorm) / (max - min))) + 120;
  } else if (max === bNorm) {
    hue = (60 * ((rNorm - gNorm) / (max - min))) + 240;
  }

  // Calculate the saturation
  let saturation = (max - min) / max;

  // Calculate the value
  let value = max;

  // Return the HSV color as a string
  return `hsv(${hue}, ${saturation * 100}, ${value * 100})`;
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in RGB
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the value (V)
  let v = max;

  // Calculate the saturation (S)
  let s = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue (H)
  let h;
  if (max === min) {
    h = 0;
  } else if (max === r) {
    h = (g - b) / (max - min) % 6;
  } else if (max === g) {
    h = (b - r) / (max - min) + 2;
  } else if (max === b) {
    h = (r - g) / (max - min) + 4;
  }

  // Convert hue to degrees
  h *= 60;

  // Ensure hue is within the range [0, 360)
  h = h % 360;

  return { h, s, v };
}

