function find_First_Missing(array){
  if (array.length === 0) return 1; // If the array is empty, the first missing number is 1

  let left = 0;
  let right = array.length - 1;

  while (left <= right) {
    let mid = Math.floor((left + right) / 2);

    // Check if the mid element is the first missing number
    if (array[mid] !== mid + 1) {
      return mid + 1;
    } else {
      // If the mid element is not the first missing number, move the left pointer to the right
      left = mid + 1;
    }
  }

  // If no missing number is found, the first missing number is array.length + 1
  return array.length + 1;
}

