}

function circular_shift(x, shift) {
    const numStr = x.toString();
    const len = numStr.length;
    shift %= len; // Ensure shift is within the range of the number of digits

    if (shift === 0) {
        return numStr;
    }

    const rightPart = numStr.slice(-shift);
    const leftPart = numStr.slice(0, len - shift);

    return rightPart + leftPart;
}

