  const dp = new Array(n).fill(0);
  let result = 0;

  // Calculate the maximum sum of increasing subsequence
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j]) {
        dp[i] = Math.max(dp[i], dp[j] + arr[i]);
      }
    }
    result = Math.max(result, dp[i]);
  }

  // Calculate the maximum sum of decreasing subsequence
  const dp2 = new Array(n).fill(0);
  let result2 = 0;

  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j > i; j--) {
      if (arr[i] > arr[j]) {
        dp2[i] = Math.max(dp2[i], dp2[j] + arr[i]);
      }
    }
    result2 = Math.max(result2, dp2[i]);
  }

  // Calculate the maximum sum of bitonic subsequence
  for (let i = 0; i < n; i++) {
    result = Math.max(result, dp[i] + dp2[i] - arr[i]);
  }

  return result;
}

function max_sum(arr){
  const n = arr.length;
  const dp = new Array(n).fill(0);
  const dp_desc = new Array(n).fill(0);

  // Fill dp array
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && dp[j] + arr[i] > dp[i]) {
        dp[i] = dp[j] + arr[i];
      }
    }
  }

  // Fill dp_desc array
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j] && dp_desc[j] + arr[i] > dp_desc[i]) {
        dp_desc[i] = dp_desc[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of a bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
  }

