function minPath(grid, k) {
    const N = grid.length;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let minPath = [];
    let visited = new Set();

    const dfs = (x, y, path) => {
        if (path.length === k) {
            minPath = path.slice();
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
                visited.add(`${nx},${ny}`);
                dfs(nx, ny, path.concat(grid[nx][ny]));
                visited.delete(`${nx},${ny}`);
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited.add(`${i},${j}`);
            dfs(i, j, [grid[i][j]]);
            visited.delete(`${i},${j}`);
        }
    }

    return minPath;
}

function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(rows).fill().map(() => new Array(cols).fill(false));
  const path = [];

  function dfs(row, col, pathLength) {
    if (pathLength === k) {
      path.push(...grid[row][col]);
      return;
    }

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path.push(grid[newRow][newCol]);
        dfs(newRow, newCol, pathLength + 1);
        path.pop();
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  return path;
}

