function rgb_to_hsv(r, g, b){
    // Normalize the RGB values to the range [0, 1]
    r = r / 255;
    g = g / 255;
    b = b / 255;

    // Find the maximum and minimum values
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the saturation
    let s = max === 0 ? 0 : (max - min) / max;

    // Calculate the value
    let v = max;

    // Calculate the hue
    let h;
    if (s === 0) {
        h = 0;
    } else {
        if (r === max) {
            h = (g - b) / (max - min);
        } else if (g === max) {
            h = 2 + (b - r) / (max - min);
        } else {
            h = 4 + (r - g) / (max - min);
        }
        h *= 60;
        if (h < 0) {
            h += 360;
        }
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let hue;
    if (delta === 0) {
        hue = 0;
    } else if (max === r) {
        hue = 60 * ((g - b) / delta);
    } else if (max === g) {
        hue = 60 * ((b - r) / delta) + 120;
    } else {
        hue = 60 * ((r - g) / delta) + 240;
    }

    hue = hue % 360;

    let saturation = (max === 0) ? 0 : delta / max;
    let value = max;

    return {
        h: hue,
        s: saturation,
        v: value
    };
}

