function find_First_Missing(array){
    let start = 0;
    let end = array.length - 1;

    while (start <= end) {
        let mid = Math.floor((start + end) / 2);

        // If the mid element is equal to its index, it means the missing number is on the right side
        if (array[mid] === mid) {
            start = mid + 1;
        } else {
            // If the mid element is not equal to its index, it means the missing number is on the left side
            end = mid - 1;
        }
    }

    // When start exceeds end, start will be the smallest missing number
    return start;
}

