function max_sum_increasing_subseq(a, n, index, k) {
    const dp = new Array(n).fill(0);
    let maxSum = 0;

    for (let i = index; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (a[j] < a[i] && dp[j] + a[i] > dp[i]) {
                dp[i] = dp[j] + a[i];
            }
        }
        if (a[i] > a[k]) {
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n || k >= n) {
        return 0;
    }

    // Calculate the maximum sum without including the kth element
    let max_sum_without_k = max_sum_increasing_subseq(a, n, index + 1, k);

    // Calculate the maximum sum including the kth element
    let max_sum_with_k = 0;
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            max_sum_with_k = Math.max(max_sum_with_k, a[index] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    return Math.max(max_sum_without_k, max_sum_with_k);
}

