function toggle_middle_bits(n) {
    // Shift the number to the left by 1 bit to isolate the second last bit
    let secondLastBit = n >> 1;
    // Toggle the second last bit
    secondLastBit ^= 1;
    // Shift the number back to the right by 1 bit to restore the original number
    let result = secondLastBit << 1;
    // Shift the original number to the left by 1 bit to isolate the first bit
    let firstBit = n >> 1;
    // Toggle the first bit
    firstBit ^= 1;
    // Shift the number back to the right by 1 bit to restore the original number
    result |= firstBit;
    return result;
}

