function rearrange_bigger(n) {
  const digits = n.toString().split('').map(Number);
  let i = digits.length - 2;

  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  if (i === -1) {
    return -1; // No bigger number can be formed
  }

  let j = i + 1;
  while (j < digits.length && digits[j] > digits[i]) {
    j++;
  }

  [digits[i], digits[j]] = [digits[j], digits[i]];
  digits.splice(i + 1);

  digits.sort((a, b) => a - b);

  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  let digits = n.toString().split('');
  let sortedDigits = digits.slice().sort((a, b) => b - a);
  let index = digits.length - 2;

  while (index >= 0 && digits[index] >= sortedDigits[index + 1]) {
    index--;
  }

  if (index === -1) {
    return -1;
  }

  let swapIndex = digits.length - 1;
  while (digits[swapIndex] <= sortedDigits[index]) {
    swapIndex--;
  }

  [digits[index], digits[swapIndex]] = [digits[swapIndex], digits[index]];

  let result = parseInt(digits.slice(0, index + 1).join('') + sortedDigits.slice(index + 1).join(''));
  return result;
}

