function rgb_to_hsv(r, g, b) {
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  if (delta === 0) {
    h = 0;
  } else if (max === r) {
    h = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    h = (60 * ((b - r) / delta)) + 120;
  } else if (max === b) {
    h = (60 * ((r - g) / delta)) + 240;
  }

  let s;
  if (max === 0) {
    s = 0;
  } else {
    s = (delta / max) * 100;
  }

  let v = (max / 255) * 100;

  return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values of RGB
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the saturation
  let saturation = max === 0 ? 0 : (max - min) / max;

  // Calculate the value
  let value = max;

  // Calculate the hue
  let hue;
  if (saturation === 0) {
    hue = 0;
  } else {
    let delta = max - min;
    if (r === max) {
      hue = (g - b) / delta;
    } else if (g === max) {
      hue = 2 + (b - r) / delta;
    } else {
      hue = 4 + (r - g) / delta;
    }
    hue /= 6;
    if (hue < 0) hue += 1;
  }

  // Convert hue to degrees
  hue *= 360;

  return { hue, saturation, value };
}

