            results.push(current_combination.slice());
            return;
        }
        if (current_sum < 0 || index >= test_list.length) {
            return;
        }
        // Include the current element in the combination
        current_combination.push(test_list[index]);
        find_combinations_recursive(test_list, current_sum - test_list[index], index + 1, current_combination, results);
        // Exclude the current element from the combination
        current_combination.pop();
        find_combinations_recursive(test_list, current_sum, index + 1, current_combination, results);
    }

    // Initialize the results array
    const results = [];
