  function combine(arr, sum, index) {
    if (sum === 0) {
      result.push([...arr]);
      return;
    }
    if (sum < 0 || index >= arr.length) {
      return;
    }
    arr.push(arr[index]);
    combine(arr, sum - arr[index], index + 1);
    arr.pop();
    combine(arr, sum, index + 1);
  }
  combine([], 0, 0);
  return result;
}

