  const maxCount = 0;

  test.split(' ').forEach(letter => {
    if (letterCounts[letter]) {
      letterCounts[letter]++;
    } else {
      letterCounts[letter] = 1;
    }

    if (letterCounts[letter] > maxCount) {
      maxCount = letterCounts[letter];
    }
  });

  const result = {};
  for (const letter in letterCounts) {
    if (letterCounts[letter] === maxCount) {
      result[letter] = letterCounts[letter];
    }
  }

  return result;
}

function histogram(test) {
