  for(let i = 3; i <= n; i++) {
    if(i % 2 === 0) {
      result.push(result[i - 1] + result[i - 2]);
    } else {
      result.push(result[i - 1] + result[i - 2] + result[i + 1]);
    }
  }
  return result;
}

