function check_dict_case(dict){
    if (Object.keys(dict).length === 0) return false;
    const keys = Object.keys(dict);
    const lowerCase = keys.every(key => typeof key === 'string' && key.toLowerCase() === key);
    const upperCase = keys.every(key => typeof key === 'string' && key.toUpperCase() === key);
    return lowerCase || upperCase;
}

function check_dict_case(dict){
  if (Object.keys(dict).length === 0) return false;

  let allLower = true;
  let allUpper = true;

  for (let key in dict) {
    if (typeof key !== 'string') return false;

    if (key.toLowerCase() !== key) allLower = false;
    if (key.toUpperCase() !== key) allUpper = false;
  }

  return allLower || allUpper;
}

