function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (row, col, pathLength, path) => {
        if (pathLength === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPath = [...path];
            }
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, pathLength + 1, [...path, grid[newRow][newCol]]);
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPath;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathValue = Infinity;

  const dfs = (i, j, steps) => {
    if (steps === k) {
      if (path.length < minPathValue || (path.length === minPathValue && path.join(',') < minPath.join(','))) {
        minPath = [...path];
        minPathValue = path.length;
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const x = i + dx;
      const y = j + dy;
      if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
        visited[x][y] = true;
        path.push(grid[x][y]);
        dfs(x, y, steps + 1);
        path.pop();
        visited[x][y] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  return minPath;
}

