function bell_Number(n){
    // Initialize the bell number array
    const bell = new Array(n + 1).fill(0);
    bell[0] = 1; // Base case: B0 = 1

    // Compute Bell numbers using the recursive formula
    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < i; j++) {
            bell[i] += bell[j] * bell[i - j - 1];
        }
    }

    return bell[n];
}

function bell_Number(n){
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

