function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n) {
    return 0;
  }

  let maxSum = 0;
  for (let i = index + 1; i < n && a[i] > a[index]; i++) {
    maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
  }

  return Math.max(maxSum, max_sum_increasing_subseq(a, n, index + 1, k));
}

function max_sum_increasing_subseq(a, n, index, k){
  // Handle edge cases
  if (index === n || k >= n) return 0;

  // Initialize the maximum sum
  let maxSum = a[index];

  // Iterate through the remaining elements to find the maximum sum including the kth element
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index]) {
      maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
    }
  }

  // Check if the kth element is greater than the current index
  if (k < n && a[k] > a[index]) {
    maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, k, k));
  }

  return maxSum;
}

