function circular_shift(x, shift) {
    const numStr = x.toString();
    const len = numStr.length;
    shift = shift % len; // Handle shift > len case
    if (shift === 0) return numStr; // No shift needed

    const reversedPart = numStr.substring(len - shift);
    const remainingPart = numStr.substring(0, len - shift);

    return reversedPart + remainingPart;
}

function circular_shift(x, shift) {
  const str = x.toString();
  const len = str.length;
  shift %= len; // Adjust shift to be within the range of the number of digits

  if (shift === 0) {
    return str;
  }

  // Perform the circular shift
  const shifted = str.slice(-shift) + str.slice(0, -shift);

  return shifted;
}

