function is_polite(n){
  let count = 0;
  let num = 0;

  while(count < n){
    num++;
    let is_polite = true;

    for(let i = 2; i <= Math.sqrt(num); i++){
      if(num % i === 0){
        is_polite = false;
        break;
      }
    }

    if(is_polite){
      count++;
    }
  }

  return num;
}

