function max_sum(arr) {
  const n = arr.length;
  const dp = new Array(n).fill(0);
  const dpRev = new Array(n).fill(0);

  // Fill dp array
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && dp[j] + arr[i] > dp[i]) {
        dp[i] = dp[j] + arr[i];
      }
    }
  }

  // Fill dpRev array
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j] && dpRev[j] + arr[i] > dpRev[i]) {
        dpRev[i] = dpRev[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of a bitonic subsequence
  let maxSum = 0;
  for (let i = 0; i < n; i++) {
    maxSum = Math.max(maxSum, dp[i] + dpRev[i] - arr[i]);
  }

  return maxSum;
}

function max_sum(arr) {
    const n = arr.length;
    const dp = Array.from({ length: n }, () => Array(n).fill(0));
    const dpRev = Array.from({ length: n }, () => Array(n).fill(0));
    let maxSum = 0;

    // Fill dp array
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === j) {
                dp[i][j] = arr[i];
            } else if (arr[i] < arr[j]) {
                dp[i][j] = dp[i][j - 1] + arr[j];
            } else if (arr[i] > arr[j]) {
                dp[i][j] = dpRev[j][i] + arr[i];
            }
            maxSum = Math.max(maxSum, dp[i][j]);
        }
    }

    // Fill dpRev array
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            if (i === j) {
                dpRev[i][j] = arr[i];
            } else if (arr[i] < arr[j]) {
                dpRev[i][j] = dpRev[i + 1][j] + arr[i];
            } else if (arr[i] > arr[j]) {
                dpRev[i][j] = dp[i][j] + arr[j];
            }
            maxSum = Math.max(maxSum, dpRev[i][j]);
        }
    }

    // Find the maximum bitonic sum
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (arr[i] < arr[j]) {
                maxSum = Math.max(maxSum, dp[i][j] + dpRev[j][i] - arr[i]);
