function find_combinations(test_list){
  const result = [];
  const dfs = (index, sum, currentCombination) => {
    if (index === test_list.length) {
      if (sum === 0) {
        result.push(currentCombination.slice());
      }
      return;
    }
    // Include the current element in the combination
    currentCombination.push(test_list[index]);
    dfs(index + 1, sum - test_list[index], currentCombination);
    // Exclude the current element from the combination
    currentCombination.pop();
    dfs(index + 1, sum, currentCombination);
  };
  dfs(0, 0, []);
  return result;
}

function find_combinations(test_list) {
    // Initialize an empty array to store the combinations
    let combinations = [];

    // Helper function to recursively find combinations
    function find_combinations_recursive(index, current_sum, current_combination) {
        // Base case: if the current combination sum equals the target sum
        if (current_sum === 0) {
            combinations.push(current_combination.slice());
            return;
        }

        // If the current index is out of bounds or the current sum exceeds the target sum
        if (index >= test_list.length || current_sum < 0) {
            return;
        }

        // Include the current element in the combination
        current_combination.push(test_list[index]);
        find_combinations_recursive(index + 1, current_sum - test_list[index], current_combination);

        // Exclude the current element from the combination
        current_combination.pop();
        find_combinations_recursive(index + 1, current_sum, current_combination);
    }

    // Start the recursion with an empty combination and the initial sum
    find_combinations_recursive(0, 0, []);

    return combinations;
}

