function max_sum(arr){
  let n = arr.length;
  let dp = Array.from({ length: n }, () => Array(n).fill(0));
  let dpRev = Array.from({ length: n }, () => Array(n).fill(0));

  // Fill dp table for increasing subsequence
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      if (arr[i] < arr[j]) {
        dp[i][j] = Math.max(dp[i][j], dp[i - 1][j] + arr[i]);
      }
    }
  }

  // Fill dpRev table for decreasing subsequence
  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (i === j) continue;
      if (arr[i] > arr[j]) {
        dpRev[i][j] = Math.max(dpRev[i][j], dpRev[i + 1][j] + arr[i]);
      }
    }
  }

  let maxSum = 0;
  // Find the maximum sum of bitonic subsequence
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      maxSum = Math.max(maxSum, dp[i][j] + dpRev[i][j] - arr[i]);
    }
  }

  return maxSum;
}

