function minPath(grid, k) {
  const N = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
  const path = [];
  let minPathLength = Infinity;
  let minPathValues = [];

  function dfs(row, col, steps) {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path.push(grid[newRow][newCol]);
        dfs(newRow, newCol, steps + 1);
        path.pop();
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      path.push(grid[i][j]);
      dfs(i, j, 1);
      path.pop();
      visited[i][j] = false;
    }
  }

  return minPathValues;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const queue = new Queue();
    const path = [];

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            queue.enqueue({ row: i, col: j, steps: 0 });
            visited.add(`${i},${j}`);
        }
    }

    while (!queue.isEmpty()) {
        const { row, col, steps } = queue.dequeue();

        if (steps === k) {
            path.push(grid[row][col]);
            return path;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                queue.enqueue({ row: newRow, col: newCol, steps: steps + 1 });
                visited.add(`${newRow},${newCol}`);
            }
        }
    }

    return [];
}

