function max_sum(arr){
  let n = arr.length;
  let dp = new Array(n).fill(0);
  let dp_desc = new Array(n).fill(0);
  let result = 0;

  // Fill dp array
  for (let i = 0; i < n; i++) {
    dp[i] = arr[i];
    for (let j = 0; j < i; j++) {
      if (arr[j] < arr[i]) {
        dp[i] = Math.max(dp[i], dp[j] + arr[i]);
      }
    }
  }

  // Fill dp_desc array
  for (let i = n - 1; i >= 0; i--) {
    dp_desc[i] = arr[i];
    for (let j = n - 1; j > i; j--) {
      if (arr[j] < arr[i]) {
        dp_desc[i] = Math.max(dp_desc[i], dp_desc[j] + arr[i]);
      }
    }
  }

  // Find the maximum sum of a bitonic subsequence
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (dp[i] + dp_desc[j] > result) {
        result = dp[i] + dp_desc[j];
      }
    }
  }

  return result;
}

