function rgb_to_hsv(r, g, b) {
  // Normalize the RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in the RGB array
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);

  // Calculate the value (V)
  const v = max;

  // Calculate the saturation (S)
  const s = max === 0 ? 0 : (v - min) / v;

  // Calculate the hue (H)
  let h = 0;
  if (max === r) {
    h = (g - b) / (max - min);
  } else if (max === g) {
    h = 2 + (b - r) / (max - min);
  } else if (max === b) {
    h = 4 + (r - g) / (max - min);
  }

  // Convert the hue from radians to degrees
  h *= 180 / Math.PI;

  // Ensure the hue is within the range [0, 360]
  h %= 360;

  return { h, s, v };
}

