function rearrange_bigger(n) {
    // Convert the number to an array of digits
    const digits = Array.from(String(n));

    // Find the index of the last digit that is smaller than the digit immediately after it
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is already the largest permutation
    if (i === -1) {
        return -1; // No bigger permutation exists
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of the found digit
    digits.splice(i + 1);

    // Convert the array of digits back to a number
    return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  let digits = n.toString().split('');
  let sortedDigits = digits.slice().sort((a, b) => b - a);
  let i = digits.length - 2;

  while (i >= 0 && digits[i] >= sortedDigits[i + 1]) {
    i--;
  }

  if (i === -1) {
    return -1; // The number is the largest possible permutation.
  }

  let j = i + 1;
  while (j < digits.length && digits[j] <= sortedDigits[i]) {
    j++;
  }

  [digits[i], digits[j]] = [digits[j], digits[i]];
  let rightPart = sortedDigits.slice(i + 1);
  digits = digits.slice(0, i + 1).concat(rightPart);

  return parseInt(digits.join(''));
}

