  let position = 0;
  let jumps = 0;

  // Iterate until the current position is greater than or equal to the target position
  while (position < d) {
    // Calculate the maximum distance that can be reached from the current position
    let maxReach = Math.min(position + steps, d);

    // Move to the maximum reachable position
    position = maxReach;

    // Increment the number of jumps
    jumps++;

    // If the maximum reachable position is greater than or equal to the target position, return the number of jumps
    if (position >= d) {
