function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    if (delta === 0) {
        return [0, 0, max]; // Black or white
    }

    let h;
    let s;
    if (max === r) {
        h = (g - b) / delta;
    } else if (max === g) {
        h = 2 + (b - r) / delta;
    } else {
        h = 4 + (r - g) / delta;
    }

    h /= 6;
    if (h < 0) h += 1;
    if (h > 1) h -= 1;

    s = delta / max;

    return [h, s, max];
}

function rgb_to_hsv(r, g, b) {
    // Ensure r, g, b are within the range [0, 255]
    r = Math.max(0, Math.min(255, r));
    g = Math.max(0, Math.min(255, g));
    b = Math.max(0, Math.min(255, b));

    // Calculate the maximum and minimum values
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the value (V)
    let v = max;

    // Calculate the saturation (S)
    let s = max === 0 ? 0 : (max - min) / max;

    // Calculate the hue (H)
    let h;
    if (max === min) {
        h = 0;
    } else if (r === max) {
        h = (g - b) / (max - min);
    } else if (g === max) {
        h = 2 + (b - r) / (max - min);
    } else {
        h = 4 + (r - g) / (max - min);
    }

    // Normalize the hue to be in the range [0, 360)
    h = (h + 360) % 360;

    return { h, s, v };
}

