    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    let minPathLength = Infinity;
    let minPathValues = [];

    const dfs = (i, j, pathLength, pathValues) => {
        if (pathLength === k) {
            if (pathValues.length < minPathLength) {
                minPathLength = pathValues.length;
                minPathValues = path.slice();
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const x = i + dx;
            const y = j + dy;
            if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
                visited[x][y] = true;
                path.push(grid[x][y]);
                dfs(x, y, pathLength + 1, pathValues);
                path.pop();
                visited[x][y] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited = new Array(N).fill().map(() => new Array(N).fill(false));
            path = [];
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPathValues;
}

