function max_sum_increasing_subseq(a, n, index, k) {
  if (index >= n) return 0;
  if (k >= n) return max_sum_increasing_subseq(a, n, index + 1, k);

  let max_sum = a[index];
  for (let i = index + 1; i < n && a[i] > a[index]; i++) {
    max_sum = Math.max(max_sum, max_sum_increasing_subseq(a, n, i, k) + a[index]);
  }

