}

function find_combinations(test_list){
    function combine(arr, targetSum, currentSum, index, result) {
        if (currentSum === targetSum) {
            result.push([...current]);
            return;
        }
        for (let i = index; i < arr.length; i++) {
            current.push(arr[i]);
            combine(arr, targetSum, currentSum + arr[i], i + 1, result);
            current.pop();
        }
    }

    let result = [];
    for (let i = 0; i < test_list.length; i++) {
        combine(test_list[i], test_list[i].reduce((a, b) => a + b), 0, 0, result);
    }
    return result;
}

function find_combinations(test_list) {
  const result = [];

  function backtrack(start, current_sum, current_combination) {
    if (current_sum === 0) {
      result.push([...current_combination]);
      return;
    }

    for (let i = start; i < test_list.length; i++) {
      if (test_list[i] > current_sum) continue;
      current_combination.push(test_list[i]);
      backtrack(i + 1, current_sum - test_list[i], current_combination);
      current_combination.pop();
    }
  }

  backtrack(0, 0, []);
  return result;
}

