    const rc = (max - r) / delta;
    const gc = (max - g) / delta;
    const bc = (max - b) / delta;

    if (r === max) {
      h = (gc - bc) / delta;
    } else if (g === max) {
      h = 2 + (bc - rc) / delta;
    } else {
      h = 4 + (rc - gc) / delta;
    }

    h = h / 6;
  }

  return [h, s, v];
}

