function find_combinations(test_list) {
  const result = [];
  const dfs = (i, currentSum, path) => {
    if (i === test_list.length) {
      if (currentSum === 0) {
        result.push(path.slice());
      }
      return;
    }
    // Include the current element
    path.push(test_list[i]);
    dfs(i + 1, currentSum + test_list[i], path);
    // Exclude the current element
    path.pop();
    dfs(i + 1, currentSum, path);
  };
  dfs(0, 0, []);
  return result;
}

function find_combinations(test_list){
    let result = [];
    function backtrack(start, currentSum, currentCombination) {
        if (currentSum === 0) {
            result.push([...currentCombination]);
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            if (test_list[i] <= currentSum) {
                currentCombination.push(test_list[i]);
                backtrack(i + 1, currentSum - test_list[i], currentCombination);
                currentCombination.pop();
            }
        }
    }
    backtrack(0, 0, []);
    return result;
}

