function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const pq = new PriorityQueue((a, b) => a[0] - b[0]);
    pq.enqueue([0, 0, 0, [grid[0][0]]]);

    while (!pq.isEmpty()) {
        const [cost, row, col, path] = pq.dequeue();
        if (path.length === k) return path;

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                pq.enqueue([cost + 1, newRow, newCol, [...path, grid[newRow][newCol]]]);
            }
        }
    }

    return [];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Set();
    const minPath = [];

    function dfs(row, col, length) {
        if (length === k) {
            minPath.push(...grid[row][col]);
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                dfs(newRow, newCol, length + 1);
                visited.delete(`${newRow},${newCol}`);
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1);
        }
    }

    minPath.sort((a, b) => a - b);
    return minPath;
}

