function rgb_to_hsv(r, g, b) {
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const delta = max - min;

    let h;
    if (delta === 0) {
        h = 0;
    } else if (max === r) {
        h = (g - b) / delta;
    } else if (max === g) {
        h = 2 + (b - r) / delta;
    } else if (max === b) {
        h = 4 + (r - g) / delta;
    }

    h = h * 60;
    if (h < 0) h += 360;

    const s = delta === 0 ? 0 : delta / max;
    const v = max / 255;

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in RGB
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);

  // Calculate the value (V) component
  const v = max;

  // Calculate the saturation (S) component
  const s = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue (H) component
  let h = 0;
  if (max === min) {
    h = 0; // Hue is undefined
  } else if (max === r) {
    h = (g - b) / (max - min);
  } else if (max === g) {
    h = 2 + (b - r) / (max - min);
  } else {
    h = 4 + (r - g) / (max - min);
  }

  // Convert hue from radians to degrees
  h *= 180 / Math.PI;

  // Ensure hue is within the range [0, 360)
  h = h % 360;

  return { h, s, v };
}

