function newman_shanks_williams(n) {
  let a = 2;
  let b = 1;
  let d = 1;
  let t = 0;
  let u = 1;

  while (true) {
    let k = 2 * t * t + 1;
    let m = 2 * t * u + 1;
    let r = b - d * Math.pow(a, k);
    if (r === 0) {
      return true;
