function eulerian_num(n, m) {
    if (n === 0 && m === 0) return 1;
    if (n < m) return 0;
    if (m === 0) return 1;
    if (n === m) return 2;

    return (n - m) * eulerian_num(n - 1, m) + eulerian_num(n - 1, m - 1);
}

function eulerian_num(n, m) {
  if (n < m || n < 0 || m < 0) {
    return "Invalid input. Please provide non-negative integers n and m.";
  }

  if (n === m) {
    return 1;
  }

  if (n === 0) {
    return 1;
  }

  let result = 0;
  for (let i = 0; i <= m; i++) {
    result += Math.pow(-1, i) * Math.comb(m, i) * Math.pow(n - i, m);
  }

  return result;
}

function encode(message) {
