function k_smallest_pairs(nums1, nums2, k) {
    // Sort both arrays to facilitate the use of a min-heap
    nums1.sort((a, b) => a - b);
    nums2.sort((a, b) => a - b);

    // Initialize a min-heap with the first element from each array
    const minHeap = new MinHeap();
    minHeap.push([nums1[0], nums2[0], 0, 0]);

    // Initialize an array to store the result pairs
    const result = [];

    // Continue popping elements from the min-heap until we reach the desired number of pairs
    while (result.length < k && !minHeap.isEmpty()) {
        const [num1, num2, i, j] = minHeap.pop();

        // Add the current pair to the result
        result.push([num1, num2]);

        // If there is a next element in nums1, push it onto the min-heap
        if (i + 1 < nums1.length) {
            minHeap.push([nums1[i + 1], num2, i + 1, j]);
        }

        // If there is a next element in nums2, push it onto the min-heap
        if (j + 1 < nums2.length) {
            minHeap.push([num1, nums2[j + 1], i, j + 1]);
        }
    }

    return result;
}

