function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  let s;

  if (delta === 0) {
    h = 0;
  } else if (max === r) {
    h = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    h = (60 * ((b - r) / delta)) + 120;
  } else {
    h = (60 * ((r - g) / delta)) + 240;
  }

  s = delta / max;

  return { h, s, v: max };
}

function rgb_to_hsv(r, g, b) {
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;
    if (max === r) {
      h = (g - b) / delta;
    } else if (max === g) {
      h = (b - r) / delta + 2;
    } else {
      h = (r - g) / delta + 4;
    }
    h /= 6;
    if (h < 0) h += 1;
  }

  return [h * 360, s * 100, v * 100];
}

