            if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
                neighbors.push([x, y]);
            }
        }
        return neighbors;
    };

    const dfs = (i, j, path, steps) => {
        if (steps === k) {
            pq.push([path.join(' '), 0]);
            return;
        }

        visited[i][j] = true;
        visitedNodes.add(`${i},${j}`);

        for (const [x, y] of getNeighbors(i, j)) {
            dfs(x, y, path + grid[x][y], steps + 1);
        }

        visited[i][j] = false;
        visitedNodes.delete(`${i},${j}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, grid[i][j], 1);
        }
    }

    pq.sort((a, b) => a[1] - b[1]);
    return pq.peek()[0].split(' ').map(Number);
}

function rearrange_bigger(n) {
    let digits = Array.from(String(n), Number);
    let len = digits.length;

    // Find the first digit that is smaller than the digit immediately after it
    let i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        return -1; // The number is the largest possible permutation
    }

    // Find the smallest digit to the right of i that is larger than digits[i]
    let j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of i
    let left = i + 1, right = len - 1;
    while (left < right) {
        [digits[left], digits[right]] = [digits[right], digits[left]];
        left++;
        right--;
    }

    return parseInt(digits.join(''));
}

