function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r = r / 255;
  g = g / 255;
  b = b / 255;

  // Find the maximum and minimum values
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the value (V)
  let v = max;

  // Calculate the saturation (S)
  let s = 0;
  if (v !== 0) {
    s = (v - min) / v;
  }

  // Calculate the hue (H)
  let h = 0;
  if (s !== 0) {
    if (r === max) {
      h = (g - b) / (2 * s);
    } else if (g === max) {
      h = (b - r) / (2 * s) + 1;
    } else {
      h = (r - g) / (2 * s) + 2;
    }
    h = h / 6;
    if (h < 0) {
      h += 1;
    }
  }

  // Convert hue to degrees
  h = h * 360;

  return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to the range [0, 1]
    r = r / 255;
    g = g / 255;
    b = b / 255;

    // Find the maximum and minimum values in the RGB array
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the value (V)
    let v = max;

    // Calculate the saturation (S)
    let s = max === 0 ? 0 : (max - min) / max;

    // Calculate the hue (H)
    let h = 0;
    if (max === min) {
        h = 0;
    } else if (max === r) {
        h = (g - b) / (max - min);
    } else if (max === g) {
        h = 2 + (b - r) / (max - min);
    } else if (max === b) {
        h = 4 + (r - g) / (max - min);
    }

    // Convert hue from radians to degrees
    h = h * 180 / Math.PI;

    // Ensure hue is within the range [0, 360)
    h = h % 360;

    return [h, s, v];
}

