function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n).fill(0);
    dp[index] = a[index];
    let max_sum = dp[index];

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
            max_sum = Math.max(max_sum, dp[i]);
        }
    }

    for (let i = index + 1; i < k; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
            max_sum = Math.max(max_sum, dp[i]);
        }
    }

    return max_sum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n - 1) {
        return a[index];
    }

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index] && i > k) {
            maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
        }
    }

    return maxSum;
}

