  function sum_combinations(arr, target, index, current_sum, combinations) {
    if (current_sum === target) {
      combinations.push(current_sum);
      return;
    }
    if (current_sum > target || index >= arr.length) {
      return;
    }
    sum_combinations(arr, target, index + 1, current_sum + arr[index], combinations);
    sum_combinations(arr, target, index + 1, current_sum, combinations);
  }

  const result = [];
  sum_combinations(test_list, 0, 0, 0, result);
