function find_combinations(test_list) {
    const result = [];
    const length = test_list.length;
    const sum = test_list.reduce((acc, val) => acc + val, 0);

    const backtrack = (start, currentSum, currentCombination) => {
        if (currentSum === sum) {
            result.push(currentCombination);
            return;
        }
        if (currentSum > sum) {
            return;
        }
        for (let i = start; i < length; i++) {
            backtrack(i + 1, currentSum + test_list[i], [...currentCombination, test_list[i]]);
        }
    };

    backtrack(0, 0, []);
    return result;
}

