function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

  // Helper function to perform BFS
  function bfs(start, visited, path) {
    if (path.length === k) {
      return path;
    }

    const queue = [[start, path]];
    while (queue.length) {
      const [current, currentPath] = queue.shift();

      for (const [dx, dy] of directions) {
        const newX = current[0] + dx;
        const newY = current[1] + dy;

        if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited[newX][newY]) {
          visited[newX][newY] = true;
          queue.push([[newX, newY], [...currentPath, grid[newX][newY]]]);
        }
      }
    }

    return null;
  }

  // Find the minimum path
  let minPathFound = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const visited = new Array(N).fill(false).map(() => new Array(N).fill(false));
      const result = bfs([i, j], visited, []);
      if (result && (minPathFound === null || result.length < minPathFound.length)) {
        minPathFound = result;
      }
    }
  }

  return minPathFound;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const paths = [];

  const dfs = (x, y, path, steps) => {
    if (steps === k) {
      paths.push(path.slice());
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, path.concat(grid[nx][ny]), steps + 1);
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, [grid[i][j]], 1);
    }
  }

  paths.sort((a, b) => {
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return a.length - b.length;
  });

  return paths[0];
}

