function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const visited = new Array(rows).fill().map(() => new Array(cols).fill(false));
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const path = [];
  const minPathLength = Infinity;
  const minPathValues = [];

  const dfs = (i, j, steps) => {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    if (i < 0 || i >= rows || j < 0 || j >= cols || visited[i][j]) {
      return;
    }

    visited[i][j] = true;
    path.push(grid[i][j]);

    for (const [dx, dy] of directions) {
      dfs(i + dx, j + dy, steps + 1);
    }

    path.pop();
    visited[i][j] = false;
  };

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      dfs(i, j, 0);
    }
  }

  return minPathValues;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const minPathLength = Infinity;
    const minPathValues = [];

    const dfs = (row, col, pathLength, path) => {
        if (pathLength === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPathValues = path.slice();
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const newRow = row + dy;
            const newCol = col + dx;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, pathLength + 1, [...path, grid[newRow][newCol]]);
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, 1, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    return minPathValues;
}

