function rgb_to_hsv(r, g, b) {
  // Convert RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in the RGB array
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);

  // Calculate the value (V)
  const v = max;

  // Calculate the saturation (S)
  const s = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue (H)
  let h;
  if (max === min) {
    h = 0;
  } else if (max === r) {
    h = (g - b) / (max - min);
  } else if (max === g) {
    h = 2 + (b - r) / (max - min);
  } else if (max === b) {
    h = 4 + (r - g) / (max - min);
  }

  // Normalize the hue to be in the range [0, 360)
  h = Math.round(h * 60);

  return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    if (delta === 0) {
        return [0, 0, max]; // Black or white
    }

    let h;
    if (max === r) {
        h = (g - b) / delta;
    } else if (max === g) {
        h = 2 + (b - r) / delta;
    } else {
        h = 4 + (r - g) / delta;
    }

    h = Math.fmod(h, 6);

    let s = delta / max;
    let v = max;

    return [h, s, v];
}

