  // Continue until the result array has k pairs or the heap is empty
  while (result.length < k && minHeap.size() > 0) {
    // Extract the smallest pair from the heap
    const [num1, num2, i, j] = minHeap.pop();

    // Add the pair to the result array
    result.push([num1, num2]);

    // If there is a next element in nums1, push it to the heap
    if (i + 1 < nums1.length) {
      minHeap.push([nums1[i + 1], num2, i + 1, j]);
    }

    // If there is a next element in nums2, push it to the heap
