      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
        visited.add(`${nx},${ny}`);
        dfs(nx, ny, steps + 1);
        visited.delete(`${nx},${ny}`);
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited.clear();
      path.length = 0;
      dfs(i, j, 0);
      if (path.length === k) {
        return path;
      }
    }
  }

  throw new Error('No path of length k found');
