    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (row, col, pathLength, path) => {
        if (pathLength === k) {
            if (pathLength < minPathLength || (pathLength === minPathLength && path.join('') < minPath.join(''))) {
                minPathLength = pathLength;
                minPath = path;
            }
            return;
        }

        visited[row][col] = true;
        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                dfs(newRow, newCol, pathLength + 1, path.concat(grid[newRow][newCol]));
            }
        }
        visited[row][col] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPath;
}

