  r = r / 255;
  g = g / 255;
  b = b / 255;

  // Calculate the maximum and minimum RGB values
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the value (V)
  let v = max;

  // Calculate the saturation (S)
  let s = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue (H)
  let h;
  if (max === min) {
    h = 0;
  } else if (r === max) {
    h = (g - b) / (max - min);
  } else if (g === max) {
    h = 2 + (b - r) / (max - min);
  } else {
    h = 4 + (r - g) / (max - min);
  }

  // Normalize the hue to the range [0, 360]
  h = (h + 360) % 360;

  return [h, s, v];
}

