  let min_element = test_list[0];

  for(let i = 1; i < test_list.length; i++){
    if(test_list[i] < min_element){
      min_element = test_list[i];
    }
    max_diff = Math.max(max_diff, test_list[i] - min_element);
  }

  return max_diff;
}

function max_difference(test_list){
  let max_diff = 0;
  for (let i = 0; i < test_list.length - 1; i++) {
    for (let j = i + 1; j < test_list.length; j++) {
      let diff = Math.abs(test_list[i] - test_list[j]);
      if (diff > max_diff) {
        max_diff = diff;
      }
    }
  }
  return max_diff;
}

